import{_ as e,o,c as r,a2 as a}from"./chunks/framework.BM5YPQmL.js";const i="/docs/screenshots/editor.png",s="/docs/screenshots/editor-dark.png",g=JSON.parse('{"title":"Home (editor)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/editor.md","filePath":"guide/editor.md","lastUpdated":1793538463000}'),d={name:"guide/editor.md"};function n(h,t,l,c,p,u){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="home-editor" tabindex="-1">Home (editor) <a class="header-anchor" href="#home-editor" aria-label="Permalink to &quot;Home (editor)&quot;">​</a></h1><p>The home view is where you format and validate JSON. It has two editors side by side: the <strong>working editor</strong> on the left and the <strong>result editor</strong> on the right. Each editor has its own toolbar above it.</p><p><img src="'+i+'" alt="Home: the working editor on the left and the formatted result on the right"></p><h2 id="formatting" tabindex="-1">Formatting <a class="header-anchor" href="#formatting" aria-label="Permalink to &quot;Formatting&quot;">​</a></h2><ul><li>Paste or type your JSON in the editor on the left.</li><li>The result editor shows the formatted JSON as you type. Formatting runs in a <strong>Web Worker</strong>, so the interface stays responsive even with large documents.</li><li>A loading indicator is shown while the formatting is in progress.</li></ul><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><ul><li>Turn on the <strong>validate json</strong> toggle in the header to be warned about invalid JSON.</li><li>When the content is not valid JSON, an <code>invalid json</code> message is shown below the editors.</li><li>Validation uses the standard <code>JSON.parse</code> rules.</li></ul><h2 id="editors" tabindex="-1">Editors <a class="header-anchor" href="#editors" aria-label="Permalink to &quot;Editors&quot;">​</a></h2><p>The editors do not capture the <strong>Tab</strong> key. Use <strong>Tab</strong> and <strong>Shift + Tab</strong> to move between an editor, its toolbar, the divider, the other editor and the header controls.</p><p>Press <strong>Alt + Shift + W</strong> to focus the working editor and <strong>Alt + Shift + R</strong> to focus the result/compare editor directly.</p><h3 id="search-inside-an-editor" tabindex="-1">Search inside an editor <a class="header-anchor" href="#search-inside-an-editor" aria-label="Permalink to &quot;Search inside an editor&quot;">​</a></h3><p>Each toolbar has a search button that opens the CodeMirror search panel in the corresponding editor. The search supports plain text and regular expressions. Press <strong>Esc</strong> to close it.</p><h3 id="resizing-the-editors" tabindex="-1">Resizing the editors <a class="header-anchor" href="#resizing-the-editors" aria-label="Permalink to &quot;Resizing the editors&quot;">​</a></h3><p>Drag the divider between the editors to resize them, or focus it and press the <strong>left/right arrow</strong> keys (or <strong>Home/End</strong> for the minimum/maximum width). The divider position is kept while you switch views.</p><h3 id="sync-scroll" tabindex="-1">Sync scroll <a class="header-anchor" href="#sync-scroll" aria-label="Permalink to &quot;Sync scroll&quot;">​</a></h3><p>Turn on <strong>sync scroll</strong> in the header to keep both editors on the same relative line while scrolling.</p><h2 id="left-toolbar-working-editor" tabindex="-1">Left toolbar (working editor) <a class="header-anchor" href="#left-toolbar-working-editor" aria-label="Permalink to &quot;Left toolbar (working editor)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>Description</th></tr></thead><tbody><tr><td>Search</td><td>Open the search panel inside the JSON editor</td></tr><tr><td>Paste from clipboard</td><td>Paste the clipboard content into the editor</td></tr><tr><td>Upload JSON file</td><td>Select a <code>.json</code> file and load it</td></tr><tr><td>Delete all</td><td>Clear the editors</td></tr></tbody></table><blockquote><p>The paste button is disabled when the browser does not support the Clipboard API.</p></blockquote><h2 id="right-toolbar-result-editor" tabindex="-1">Right toolbar (result editor) <a class="header-anchor" href="#right-toolbar-result-editor" aria-label="Permalink to &quot;Right toolbar (result editor)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>Description</th></tr></thead><tbody><tr><td>Search</td><td>Open the search panel inside the result editor</td></tr><tr><td>Space tabulation</td><td>Set the indentation width in spaces (2 by default)</td></tr><tr><td>Clean spaces</td><td>Remove all spaces</td></tr><tr><td>Clean new lines</td><td>Remove all line breaks</td></tr><tr><td>Clean new lines and spaces</td><td>Remove line breaks and spaces</td></tr><tr><td>Copy JSON</td><td>Copy the formatted result to the clipboard</td></tr></tbody></table><blockquote><p>The copy button is disabled when the browser does not support the Clipboard API. All the toolbar buttons show their purpose as a tooltip when you hover over them.</p></blockquote><p>Every toolbar action also has a keyboard shortcut. See <a href="/docs/guide/keyboard">Keyboard shortcuts</a> for the list.</p><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><p>When the <strong>JSON History</strong> feature is enabled (default), json-tool records the JSON you have used. Open the drawer from the header (or press <strong>Alt + H</strong>) to see the entries:</p><ul><li><strong>Send to editor</strong> — put the entry back into the working editor.</li><li><strong>Copy</strong> — copy the full content of the entry to the clipboard.</li></ul><p>Press <strong>Esc</strong> or use the close button to close the drawer. The drawer keeps the keyboard focus inside it while it is open.</p><p>The drawer shows a short snippet of each entry and the full content is stored for the actions above. It is empty until you start using the editor.</p><p>json-tool also ships with a dark theme, switched from the header:</p><p><img src="'+s+'" alt="Home in dark mode"></p>',30)])])}const m=e(d,[["render",n]]);export{g as __pageData,m as default};
